package secrets

import (
	"crypto/rand"
	"encoding/base64"
	"encoding/hex"
	"errors"
	"fmt"
	"math/big"
	"strconv"
)

// SecretSpec declares the desired shape of an auto-generated secret. It is
// passed to Manager.EnsureSecret to describe a secret that must exist, and
// defines exactly how a fresh value is generated when the backing secret
// does not yet exist at the requested path.
//
// Once a secret has been generated under a given spec and stored, a
// subsequent EnsureSecret call for the same path with a DIFFERENT spec
// returns ErrSecretSpecMismatch. EnsureSecret never silently rotates or
// regenerates. An operator who needs to change the spec must explicitly
// rotate the secret via Store() (which bumps the version) or Delete() +
// fresh EnsureSecret.
//
// Encoding values:
//
//   - "base64" — URL-safe base64 without padding, producing strings safe
//     for use in URLs, file paths, and JSON
//   - "hex"    — lowercase hexadecimal, 2 characters per byte
//   - "numeric" — base-10 digit string. Length is the number of output
//     digits, NOT the number of random bytes. Each digit is uniformly
//     sampled via crypto/rand.Int so there is no modulo bias. Typical
//     use: PINs, OTP codes.
//   - "raw"    — raw bytes returned verbatim. The length field is the
//     byte count. Callers are responsible for any subsequent encoding.
//
// Length semantics:
//
//   - For base64, hex, raw: Length is the number of random bytes generated
//     before encoding. The STORED value's byte length depends on encoding
//     (hex doubles, base64 ~= ceil(n*4/3), raw is exact).
//   - For numeric: Length is the number of output digits directly.
//
// A zero or negative Length is invalid.
type SecretSpec struct {
	// Length is the entropy length (bytes for base64/hex/raw, digits for
	// numeric).
	Length int `json:"length"`

	// Encoding is the output encoding. See SecretSpec docs for supported
	// values.
	Encoding string `json:"encoding"`
}

// Supported encoding strings. Use these constants in code instead of
// raw string literals so typos are compile errors.
const (
	EncodingBase64  = "base64"
	EncodingHex     = "hex"
	EncodingNumeric = "numeric"
	EncodingRaw     = "raw"
)

// Metadata keys used by EnsureSecret to persist the spec alongside the
// generated bytes. The presence of these keys on a stored secret marks
// it as an ensured (auto-generated) secret rather than an operator-put
// static value.
const (
	// MetaAutoGenerated marks a secret as generated by EnsureSecret.
	MetaAutoGenerated = "auto_generated"
	// MetaSpecLength is the decimal-encoded SecretSpec.Length.
	MetaSpecLength = "spec_length"
	// MetaSpecEncoding is the SecretSpec.Encoding.
	MetaSpecEncoding = "spec_encoding"
	// EnsureSecretDataKey is the single map-key under which EnsureSecret
	// stores the generated bytes inside the secret's data map. Callers
	// read the value back via data[EnsureSecretDataKey].
	EnsureSecretDataKey = "value"
)

// ErrSecretSpecMismatch indicates that a previously stored secret exists
// at the requested path, but its stored spec does not match the spec
// provided to EnsureSecret. The existing value is NOT returned — the
// caller must reconcile explicitly (rotate, delete+recreate, or fix the
// caller's expected spec).
var ErrSecretSpecMismatch = errors.New("secrets: stored secret spec does not match requested spec")

// ErrInvalidSpec indicates the SecretSpec is malformed (e.g. zero
// length, unknown encoding).
var ErrInvalidSpec = errors.New("secrets: invalid secret spec")

// Validate checks the spec for internal consistency. Returns a wrapped
// ErrInvalidSpec on any problem.
func (s *SecretSpec) Validate() error {
	if s == nil {
		return fmt.Errorf("%w: nil spec", ErrInvalidSpec)
	}
	if s.Length <= 0 {
		return fmt.Errorf("%w: length must be positive, got %d", ErrInvalidSpec, s.Length)
	}
	switch s.Encoding {
	case EncodingBase64, EncodingHex, EncodingNumeric, EncodingRaw:
		return nil
	case "":
		return fmt.Errorf("%w: encoding is required", ErrInvalidSpec)
	default:
		return fmt.Errorf("%w: unsupported encoding %q (supported: %s, %s, %s, %s)",
			ErrInvalidSpec, s.Encoding, EncodingBase64, EncodingHex, EncodingNumeric, EncodingRaw)
	}
}

// Equal returns true when two specs have identical length and encoding.
// Used by EnsureSecret to detect spec mismatches between a caller's
// requested spec and the spec recorded in a previously stored secret.
func (s *SecretSpec) Equal(other *SecretSpec) bool {
	if s == nil || other == nil {
		return s == nil && other == nil
	}
	return s.Length == other.Length && s.Encoding == other.Encoding
}

// Generate produces a fresh random value that matches the spec. Returns
// the bytes that should be stored and later returned to callers (for
// base64/hex/numeric the bytes ARE the encoded string; for raw they are
// the underlying random bytes).
//
// Uses crypto/rand exclusively.
func (s *SecretSpec) Generate() ([]byte, error) {
	if err := s.Validate(); err != nil {
		return nil, err
	}

	switch s.Encoding {
	case EncodingNumeric:
		return generateNumeric(s.Length)
	case EncodingRaw:
		return generateRaw(s.Length)
	case EncodingBase64:
		raw, err := generateRaw(s.Length)
		if err != nil {
			return nil, err
		}
		return []byte(base64.RawURLEncoding.EncodeToString(raw)), nil
	case EncodingHex:
		raw, err := generateRaw(s.Length)
		if err != nil {
			return nil, err
		}
		return []byte(hex.EncodeToString(raw)), nil
	}
	// Unreachable: Validate() rejects unsupported encodings.
	return nil, fmt.Errorf("%w: %q", ErrInvalidSpec, s.Encoding)
}

// specFromMetadata extracts and validates a SecretSpec from a stored
// secret's metadata map, if and only if the metadata marks the secret as
// auto-generated. Returns nil,nil when the metadata does not describe an
// auto-generated secret (e.g. the path was previously populated by
// operator-driven Store). Returns a non-nil error when the metadata is
// present but malformed.
func specFromMetadata(metadata map[string]string) (*SecretSpec, error) {
	if metadata == nil {
		return nil, nil
	}
	if metadata[MetaAutoGenerated] != "true" {
		return nil, nil
	}
	lenStr, ok := metadata[MetaSpecLength]
	if !ok {
		return nil, fmt.Errorf("secrets: stored auto-generated secret missing %s metadata", MetaSpecLength)
	}
	length, err := strconv.Atoi(lenStr)
	if err != nil {
		return nil, fmt.Errorf("secrets: invalid %s metadata %q: %w", MetaSpecLength, lenStr, err)
	}
	enc, ok := metadata[MetaSpecEncoding]
	if !ok {
		return nil, fmt.Errorf("secrets: stored auto-generated secret missing %s metadata", MetaSpecEncoding)
	}
	spec := &SecretSpec{Length: length, Encoding: enc}
	if err := spec.Validate(); err != nil {
		return nil, fmt.Errorf("secrets: stored spec metadata is invalid: %w", err)
	}
	return spec, nil
}

// specToMetadata merges the spec + auto-generated marker into the
// caller-supplied metadata map (which may be nil). Returns a new map
// that the caller should pass to Store.
func specToMetadata(spec *SecretSpec, callerMeta map[string]string) map[string]string {
	merged := make(map[string]string, len(callerMeta)+3)
	for k, v := range callerMeta {
		merged[k] = v
	}
	merged[MetaAutoGenerated] = "true"
	merged[MetaSpecLength] = strconv.Itoa(spec.Length)
	merged[MetaSpecEncoding] = spec.Encoding
	return merged
}

// generateRaw returns exactly n cryptographically random bytes.
func generateRaw(n int) ([]byte, error) {
	buf := make([]byte, n)
	if _, err := rand.Read(buf); err != nil {
		return nil, fmt.Errorf("secrets: entropy read failed: %w", err)
	}
	return buf, nil
}

// generateNumeric returns n ASCII digits ('0'..'9') uniformly sampled
// via crypto/rand.Int — no modulo bias.
func generateNumeric(n int) ([]byte, error) {
	ten := big.NewInt(10)
	out := make([]byte, n)
	for i := 0; i < n; i++ {
		v, err := rand.Int(rand.Reader, ten)
		if err != nil {
			return nil, fmt.Errorf("secrets: entropy read failed: %w", err)
		}
		out[i] = byte('0' + v.Int64())
	}
	return out, nil
}
